<?php use App\Services\BookingRules; $id=(int)$reservation['id']; $now=gmdate('Y-m-d H:i:s'); $minutes=intdiv((new DateTimeImmutable($reservation['end_datetime'],new DateTimeZone('UTC')))->getTimestamp()-(new DateTimeImmutable($reservation['start_datetime'],new DateTimeZone('UTC')))->getTimestamp(),60); $actions=[]; if($reservation['status']==='pending') $actions=$reservation['start_datetime']>$now && $latestDocument && $latestDocument['status']==='accepted'?['approve','reject']:['reject']; if($reservation['status']==='approved' && $reservation['start_datetime']>$now) $actions=['cancel']; if($reservation['status']==='approved' && $reservation['end_datetime']<=$now) $actions=['complete']; ?>
<div class="workspace-heading"><div><span class="status-badge <?= esc($reservation['status'],'attr') ?>"><?= esc(ucfirst($reservation['status'])) ?></span><small>Submitted <?= esc(BookingRules::display($reservation['created_at'])) ?> Manila</small></div><a class="button secondary" href="<?= site_url('admin/reservations') ?>">Back to reservations</a></div>
<div class="workspace-grid"><section class="workspace-card"><h2>Reservation Information</h2><dl class="workspace-details"><div><dt>Start (Manila)</dt><dd><?= esc(BookingRules::display($reservation['start_datetime'])) ?></dd></div><div><dt>End (Manila)</dt><dd><?= esc(BookingRules::display($reservation['end_datetime'])) ?></dd></div><div><dt>Duration</dt><dd><?= intdiv($minutes,60) ?> hr <?= $minutes%60 ?> min</dd></div><div class="workspace-full"><dt>Purpose</dt><dd class="description"><?= esc($reservation['purpose']) ?></dd></div></dl></section>
<section class="workspace-card"><h2>Borrower Information</h2><dl class="workspace-details"><?php foreach(($borrower??[]) as $key=>$value): ?><div><dt><?= esc(ucwords(str_replace('_',' ',$key))) ?></dt><dd><?= esc($value?:'Not specified') ?></dd></div><?php endforeach ?></dl></section>
<section class="workspace-card"><h2>Teacher-Signed Request Form</h2><?php if($latestDocument): ?><p>Latest review: <span class="status-badge <?= esc($latestDocument['status'],'attr') ?>"><?= esc(ucfirst($latestDocument['status'])) ?></span></p><?php foreach($documents as $document): ?><div class="document-version"><strong><?= esc($document['original_name']) ?></strong><small><?= esc($document['mime_type']) ?> · <?= esc(BookingRules::display($document['submitted_at'])) ?> Manila · <?= esc(ucfirst($document['status'])) ?></small><a href="<?= site_url('admin/reservations/'.$id.'/documents/'.$document['id']) ?>">Download form</a><?php if(!empty($document['rejection_reason'])): ?><p class="description">Rejection reason: <?= esc($document['rejection_reason']) ?></p><?php endif ?></div><?php endforeach ?><?php if($reservation['status']==='pending' && $latestDocument['status']==='pending'): ?><form method="post" action="<?= site_url('admin/reservations/'.$id.'/documents/'.$latestDocument['id'].'/review') ?>"><?= csrf_field() ?><label for="rejection_reason">Reason if rejecting the form</label><textarea id="rejection_reason" name="rejection_reason" maxlength="2000" rows="3"></textarea><div class="workspace-actions"><button type="submit" name="decision" value="accept">Accept form</button><button type="submit" name="decision" value="reject">Reject form</button></div></form><?php endif ?><?php else: ?><p>No signed form has been recorded. Approval and payment require a valid accepted form.</p><?php endif ?></section>
<section class="workspace-card"><h2>Administrator Decision</h2><?php if($reservation['reviewed_at']): ?><dl class="workspace-details"><div><dt>Administrator</dt><dd><?= esc($reviewer['full_name']??'Facilities Office') ?></dd></div><div><dt>Decision status</dt><dd><span class="status-badge <?= esc($reservation['status'],'attr') ?>"><?= esc(ucfirst($reservation['status'])) ?></span></dd></div><div><dt>Decision date</dt><dd><?= esc(BookingRules::display($reservation['reviewed_at'])) ?> Manila</dd></div><div class="workspace-full"><dt>Remarks</dt><dd class="description"><?= esc($reservation['admin_remarks']??'No remarks.') ?></dd></div></dl><?php else: ?><p>No administrator decision has been recorded.</p><?php endif ?><?php if($actions): ?><h3>Manage reservation</h3><form method="post" action="<?= site_url('admin/reservations/'.$id.'/decision') ?>"><?= csrf_field() ?><label for="remarks">Administrator remarks (required for rejection or cancellation)</label><textarea id="remarks" name="remarks" maxlength="2000" rows="3"></textarea><div class="workspace-actions"><?php foreach($actions as $action): ?><button type="submit" name="action" value="<?= $action ?>"><?= ucfirst($action) ?></button><?php endforeach ?></div></form><?php endif ?></section>
<section class="workspace-card workspace-wide"><h2>Reserved Resources</h2><div class="table-wrap"><table class="workspace-table"><thead><tr><th>Resource Name</th><th>Quantity</th><th>Hourly Rate</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= esc($item['name']) ?><?php if(!empty($item['inventory_identifier'])): ?><small>Inventory: <?= esc($item['inventory_identifier']) ?></small><?php endif ?></td><td><?= (int)$item['quantity'] ?></td><td>PHP <?= esc($item['rate_per_hour']) ?></td><td>PHP <?= esc($item['subtotal']) ?></td></tr><?php endforeach ?></tbody></table></div><p class="workspace-total">Total reservation fee: <?= esc($reservation['currency']) ?> <?= esc($reservation['total_amount']) ?></p></section>
<section class="workspace-card workspace-wide"><h2>Payment Information</h2><p>Reservation approval and payment are tracked separately.</p><?php if($payments): ?><div class="table-wrap"><table><thead><tr><th>Payment reference</th><th>Method</th><th>Payment status</th><th>Amount</th><th>Gateway transaction</th><th>Payment date</th><th>Receipt</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td><?php $ref=(string)($payment['transaction_reference']??''); if($ref!==''): ?><div class="reference-cell"><span title="<?= esc($ref,'attr') ?>"><?= esc(mb_strlen($ref)>15?mb_substr($ref,0,8).'…'.mb_substr($ref,-4):$ref) ?></span><button class="copy-reference secondary" type="button" data-reference="<?= esc($ref,'attr') ?>" aria-label="Copy transaction reference"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span></button><span class="copy-feedback" role="status" aria-live="polite"></span></div><?php else: ?>Pending reference<?php endif ?></td><td><span class="category-badge <?= esc($payment['payment_method']??'','attr') ?>"><?= esc(ucwords(str_replace('_',' ',$payment['payment_method']??''))) ?></span></td><td><span class="status-badge <?= esc($payment['payment_status'],'attr') ?>"><?= esc(ucfirst($payment['payment_status'])) ?></span></td><td><?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></td><td><?= esc($payment['gateway_transaction_id']??'Not received yet') ?></td><td><?= !empty($payment['paid_at'])?esc(BookingRules::display($payment['paid_at']).' Manila'):'Not paid' ?></td><td><?php if(!in_array($payment['payment_status'],['pending','failed'],true)): ?><a href="<?= site_url('admin/payments/'.$payment['id'].'/receipt') ?>"><?= $payment['payment_status'] === 'paid' ? 'Receipt' : 'Transaction details' ?></a><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php else: ?><p>Payment status: <span class="status-badge unpaid">Unpaid</span></p><?php endif ?></section></div>
<?= $this->endSection() ?>
